commits.patch:
diff --git a/libarchive/archive_read_support_format_ar.c b/libarchive/archive_read_support_format_ar.c
index 876cd41..1262255 100644
--- a/libarchive/archive_read_support_format_ar.c
+++ b/libarchive/archive_read_support_format_ar.c
@@ -254,7 +254,7 @@ _ar_read_header(struct archive_read *a, struct archive_entry *entry,
 	 */
 	if (strcmp(filename, "//") == 0) {
 		char *st;
-		size_t entry_size;
+		size_t entry_size, alloc_size;

 		archive_entry_copy_pathname(entry, filename);
 		/* Get the size of the filename table. */
@@ -276,8 +276,17 @@ _ar_read_header(struct archive_read *a, struct archive_entry *entry,
 			return (ARCHIVE_FATAL);
 		}

+		/*
+		 * An odd-sized table is followed by one pad byte so the
+		 * next member stays even-aligned. Keep that byte
+		 * addressable for the separator scan.
+		 */
+		alloc_size = entry_size;
+		if (ar->entry_padding == 1 && alloc_size < SIZE_MAX)
+			alloc_size++;
+
 		/* Read the filename table into memory. */
-		st = malloc(entry_size);
+		st = malloc(alloc_size);
 		if (st == NULL) {
 			archive_set_error(&a->archive, ENOMEM,
 			    "Can't allocate filename table buffer");
@@ -294,6 +303,8 @@ _ar_read_header(struct archive_read *a, struct archive_entry *entry,
 		if ((b = __archive_read_ahead(a, entry_size, NULL)) == NULL)
 			return (ARCHIVE_FATAL);
 		memcpy(st, b, entry_size);
+		if (alloc_size > entry_size)
+			st[entry_size] = '\0';
 		__archive_read_consume(a, entry_size);
 		/* All contents are consumed. */
 		ar->entry_bytes_remaining = 0;
@@ -518,13 +529,24 @@ ar_parse_gnu_filename_table(struct archive_read *a)

 	size = ar->strtab_size;

-	for (p = ar->strtab; p < ar->strtab + size - 1; ++p) {
-		/* Normalize backslash, even before separator check. */
-		if (*p == '\\')
-			*p = '/';
-		if (*p == '/' && *(p + 1) == '\n') {
-			*p++ = '\0';
-			*p = '\0';
+	/*
+	 * An odd-sized table keeps one pad byte addressable so a
+	 * separator on the last payload byte is handled like one in
+	 * the middle of the table.
+	 */
+	{
+		size_t limit = size;
+
+		if (ar->entry_padding == 1)
+			limit++;
+		for (p = ar->strtab; p < ar->strtab + limit - 1; ++p) {
+			/* Normalize backslash, even before separator check. */
+			if (*p == '\\')
+				*p = '/';
+			if (*p == '/' && *(p + 1) == '\n') {
+				*p++ = '\0';
+				*p = '\0';
+			}
 		}
 	}
 	/*

--- a/libarchive/archive_read_support_format_ar.c
+++ b/libarchive/archive_read_support_format_ar.c
@@ -310,9 +310,18 @@
 			return (ARCHIVE_FATAL);
 		memcpy(st, b, strtab_size);

-		/* Skip special file entry. */
-		if (archive_read_format_ar_skip(a) != ARCHIVE_OK)
-			return (ARCHIVE_FATAL);
+		/*
+		 * archive_read_format_ar_skip() consumes the pad byte but
+		 * clears entry_padding. The separator scan still consults
+		 * that flag for an odd-sized table, so restore it.
+		 */
+		{
+			int64_t saved_padding = ar->entry_padding;
+
+			if (archive_read_format_ar_skip(a) != ARCHIVE_OK)
+				return (ARCHIVE_FATAL);
+			ar->entry_padding = saved_padding;
+		}

 		/* Parse the filename table. */
 		return (ar_parse_gnu_filename_table(a));
